                for r, r2 in itertools.combinations(range(N), 2):
                    cl.append([-v(r, c1, a), -v(r, c2, b), -v(r2, c1, a), -v(r2, c2, b)])
    U = {}
    for r, r2 in itertools.combinations(range(N), 2):
        u = B.new()
        U[(r, r2)] = u
        wit = []
        for c in range(K):
            for s in range(Q):
                a = B.new()
                cl.append([-a, v(r, c, s)])
                cl.append([-a, v(r2, c, s)])
                wit.append(a)
        cl.append(wit + [u])
    ns = K - c0
    for r in range(N):
        lits = [U[(min(r, x), max(r, x))] for x in range(N) if x != r]
        target = (N - 1) - 2 * c0 - ns - len(member[r])
        for c in range(c0, K):
            for s in range(Q):
                n = profs[c][s]
                if n >= 2:
                    lits += [v(r, c, s)] * (n - 2)
                else:
